#!/usr/bin/env python3
"""Print the most common words in a text file."""

import argparse
import re
import sys


def count_words(text: str) -> dict[str, int]:
    """Return a dict mapping each word to its count."""
    words = re.findall(r"[a-zA-Z0-9]+", text.lower())
    freq: dict[str, int] = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1
    return freq


def main() -> None:
    parser = argparse.ArgumentParser(description="Print the most common words in a file.")
    parser.add_argument("file", help="Path to the text file")
    parser.add_argument("--top", type=int, default=10, help="Number of top words to show (default: 10)")
    args = parser.parse_args()

    try:
        with open(args.file, encoding="utf-8") as f:
            text = f.read()
    except FileNotFoundError:
        print(f"Error: file not found: {args.file}", file=sys.stderr)
        sys.exit(1)

    freq = count_words(text)
    # Sort by count descending, then alphabetically ascending for ties
    sorted_words = sorted(freq.items(), key=lambda item: (-item[1], item[0]))

    for word, count in sorted_words[: args.top]:
        print(f"{word}: {count}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Print the most common words in a text file."""

import argparse
import re
import sys


def count_words(text: str) -> dict[str, int]:
    """Return a dict mapping each word (lowercase, alphanumeric) to its count."""
    words = re.findall(r"[a-zA-Z0-9]+", text)
    counts: dict[str, int] = {}
    for w in words:
        low = w.lower()
        counts[low] = counts.get(low, 0) + 1
    return counts


def top_words(counts: dict[str, int], n: int) -> list[tuple[str, int]]:
    """Return the top *n* words sorted by count desc, then alphabetically."""
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:n]


def main() -> None:
    parser = argparse.ArgumentParser(description="Print the most common words in a file.")
    parser.add_argument("file", help="Path to the text file to analyse.")
    parser.add_argument("--top", type=int, default=10, help="Number of top words to show (default 10).")
    args = parser.parse_args()

    try:
        with open(args.file, encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        print(f"Error: file not found: {args.file}", file=sys.stderr)
        sys.exit(1)

    counts = count_words(text)
    for word, count in top_words(counts, args.top):
        print(f"{word}: {count}")


if __name__ == "__main__":
    main()
